const directionLookup = {
    "大甲": { "彰化": "逆行", "員林": "逆行", "台中": "逆行", "大慶": "逆行" },
    "彰化": { "大甲": "順行", "台中": "順行", "大慶": "順行", "員林": "逆行" },
    "大慶": { "大甲": "逆行", "彰化": "逆行", "員林": "逆行", "台中": "順行" },
    "台中": { "大甲": "逆行", "彰化": "逆行", "員林": "逆行", "大慶": "逆行" },
